'use strict';
let D;const $=s=>document.querySelector(s), cats=['Kills','Aces','Blocks','Digs','Assists'];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=v=>v==null?'—':Number(v).toLocaleString('en-US');
const serial=s=>{const [m,d,y]=String(s).split('/').map(Number);return new Date(y<100?2000+y:y,m-1,d).getTime()};
const date=s=>new Date(serial(s)).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});
const total=rows=>cats.map((_,i)=>{const v=rows.map(s=>s.values[i]).filter(v=>v!=null);return v.length?v.reduce((a,b)=>a+b,0):null});
const route=(page,params={})=>'#'+page+(Object.keys(params).length?'?'+new URLSearchParams(params):'');
const pByName=n=>D.players.find(p=>p.name===n), pLink=n=>pByName(n)?route('player',{id:pByName(n).id}):'#players';
const initial=n=>n.split(' ').filter(Boolean).map(s=>s[0]).slice(0,2).join('');
const statstrip=v=>`<div class="stat-strip">${cats.map((c,i)=>`<div><strong>${fmt(v[i])}</strong><span>${c}</span></div>`).join('')}</div>`;
const source=(url,label='View Results')=>url&&/^https:\/\/www\.aukssports\.com\//.test(url)?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`:'';
const getState=()=>{const [page='home',query='']=(location.hash.slice(1)||'home').split('?');return {page,q:new URLSearchParams(query)}};
function options(vals,current,allLabel){return (allLabel?`<option value="">${allLabel}</option>`:'')+vals.map(v=>`<option value="${esc(v)}" ${String(current)===String(v)?'selected':''}>${esc(v)}</option>`).join('')}
function select(label,key,values,current,all){return `<div class="field"><label for="${key}">${label}</label><select id="${key}" data-filter="${key}">${options(values,current,all)}</select></div>`}
function search(label,value){return `<div class="field search"><label for="search">${label}</label><input type="search" id="search" data-filter="search" placeholder="${label}" value="${esc(value)}" autocomplete="off"></div>`}
function years(){return [...new Set(D.games.map(g=>g.season))].sort((a,b)=>b-a)}
function classYears(){return [...new Set(D.players.map(p=>p.year))].sort((a,b)=>(a==='Unknown'?9999:a)-(b==='Unknown'?9999:b))}
function currentJersey(name){const year=Math.max(...D.roster.map(r=>r.season));return D.roster.find(r=>r.season===year&&r.name===name&&r.role!=='Manager')?.jersey||'';}
function jerseyMark(name){const jersey=currentJersey(name);return jersey?`<span class="jersey-mark" aria-label="Current jersey number ${esc(jersey)}"><small>NO.</small><strong>${esc(jersey)}</strong></span>`:`<span class="alumni-mark" aria-label="${esc(name)} initials"><small>${Number(pByName(name)?.year)<=Math.max(...D.roster.map(r=>r.season))?'ALUM':'ARCHIVE'}</small><strong>${esc(initial(name))}</strong></span>`;}
function playerStatstrip(values){const selected=Number(getState().q.get('stat')??-1);return `<div class="stat-strip player-stat-strip">${cats.map((c,i)=>`<button type="button" data-player-stat="${i}" aria-label="Rank games by ${c.toLowerCase()}" aria-pressed="${selected===i}"><strong>${fmt(values[i])}</strong><span>${c}</span></button>`).join('')}</div>`;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-player-stat]');if(!b)return;const {page,q}=getState();if(page!=='player')return;const value=b.dataset.playerStat;const seasonOpen=!!document.querySelector('.season-breakdown[open]');const focusIndex=[...document.querySelectorAll('[data-player-stat]')].indexOf(b);if(value==='all')q.delete('stat');else q.set('stat',value);history.replaceState(null,'',route(page,Object.fromEntries(q)));render(false);if(seasonOpen)document.querySelector('.season-breakdown').open=true;document.querySelectorAll('[data-player-stat]')[focusIndex]?.focus({preventScroll:true});});
function playerStatStory(rows,selected){if(selected<0)return 'Tap any statistic to highlight it and rank the games below.';const valid=rows.filter(r=>r.values[selected]!=null);if(!valid.length)return `No ${cats[selected].toLowerCase()} reported in the selected seasons.`;const best=Math.max(...valid.map(r=>r.values[selected]));const leaders=valid.filter(r=>r.values[selected]===best);return `<strong>${fmt(best)}</strong><span><b>Best recorded ${cats[selected].toLowerCase()}</b><small>${leaders.length===1?esc(leaders[0].opponent)+' · '+date(leaders[0].date):leaders.length+' games tied'} · ${getState().q.get('season')?'selected season':'all seasons'}</small></span>`;}
function currentRosterDetail(name){const year=Math.max(...D.roster.map(r=>r.season)),r=D.roster.find(r=>r.season===year&&r.name===name&&r.role!=='Manager');return r?`<small class="current-player-detail">${r.jersey?'#'+esc(r.jersey)+' · ':''}${r.grade?'Grade '+esc(r.grade)+' · ':''}${year} roster</small>`:'';}
function playerCard(p){return `<a class="card player-card" href="${pLink(p.name)}"><div class="top">${jerseyMark(p.name)}<div><h3>${esc(p.name)}</h3>${currentRosterDetail(p.name)}<small>${p.year==='Unknown'?'Graduation year unknown':'Class of '+p.year}</small></div><span class="arrow" aria-hidden="true">↗</span></div>${statstrip(p.values)}</a>`}
function gameCard(g){const dt=new Date(serial(g.date));return `<a class="game-card" href="${route('game',{id:g.id})}"><div class="game-date"><b>${dt.toLocaleDateString('en-US',{month:'short',day:'numeric'})}</b>${g.season}</div>${opponentMark(g.opponent)}<div class="game-body"><h3>${g.homeAway==='H'?'vs':'at'} ${esc(g.opponent)}</h3><small>${esc(g.phase)} · ${g.entries?'Player stats available':'Score only · player stats missing'}</small></div><div class="score">${esc(g.score||'—')} <span class="badge ${g.result==='L'?'loss':''}">${esc(g.result||'—')}</span></div><span class="arrow" aria-hidden="true">↗</span></a>`}
function head(title,intro,eyebrow='ARCHMERE VOLLEYBALL'){return `<div class="eyebrow">${eyebrow}</div><h1>${esc(title)}</h1>${intro?`<p class="intro">${intro}</p>`:''}`}
function note(){return `<p class="note">These are documented subtotals from available results. A dash means unreported—not zero. Published player rows do not establish games played.</p>`}
function home(){const year=Math.max(...D.roster.map(r=>r.season));const gs=D.games.filter(g=>g.season===year).sort((a,b)=>serial(b.date)-serial(a.date));return `<div class="home-page"><section class="season-banner"><div><div class="eyebrow">THE AUKS / GIRLS VARSITY VOLLEYBALL</div><div class="home-edition">SEASONS ON FILE · ${Math.min(...D.games.map(g=>g.season))}–${year}</div><h1><span>THE AUKS.</span><span class="outline-title">ON RECORD.</span></h1><p>Every season has a story.<br>Find the players, the matches, and the numbers behind them.</p><div class="banner-actions"><a class="button" href="#roster">Current roster →</a><a class="button secondary" href="#players">Find a player</a></div></div><div class="season-summary"><span>${year} SEASON</span><strong>${gs.filter(g=>g.result==='W').length}<i>–</i>${gs.filter(g=>g.result==='L').length}</strong><small>RECORDED WINS / LOSSES</small><a href="${route('season',{year})}">Season details →</a></div></section><div class="archive-bar home-archive"><a href="#seasons"><span>THE SEASONS</span><b>${Math.min(...D.games.map(g=>g.season))}–${year}</b><small>Explore the archive ↗</small></a><a href="#players"><span>THE PLAYERS</span><b>${D.players.length}</b><small>Find an Auk ↗</small></a><a href="#records"><span>THE RECORDS</span><b>Top 10</b><small>See documented leaders ↗</small></a></div><div class="split"><section class="section"><div class="section-head"><h2><span class="home-section-no">01 /</span> Latest results</h2><a class="text-link" href="${route('games',{season:year})}">All results</a></div><div class="game-list">${gs.slice(0,4).map(gameCard).join('')}</div></section><section class="section class-index"><div class="section-head"><h2><span class="home-section-no">02 /</span> Through the years</h2><a class="text-link" href="#players">All players</a></div><div class="class-list">${classYears().filter(y=>y!=='Unknown').sort((a,b)=>b-a).map(y=>`<a href="${route('players',{year:y})}"><span><em>CLASS OF</em><b>${y}</b></span><small>${D.players.filter(p=>p.year===y).length} players <span aria-hidden="true">→</span></small></a>`).join('')}</div></section></div><p class="note">Reviewed records as of ${D.updated}. Historical statistics may be incomplete. <a href="#about">Sources & coverage</a></p></div>`}
function players(q){let list=D.players.filter(p=>(!q.get('year')||String(p.year)===q.get('year'))&&(!q.get('search')||p.name.toLowerCase().includes(q.get('search').toLowerCase())));const sort=q.get('sort')||'Name';list.sort(sort==='Name'?(a,b)=>a.name.localeCompare(b.name):(a,b)=>(b.values[cats.indexOf(sort)]??-1)-(a.values[cats.indexOf(sort)]??-1));return head(q.get('year')?'Class of '+q.get('year'):'Players','Career records and game logs.')+`<div class="tools">${search('Search player names',q.get('search'))}${select('Graduation year','year',classYears(),q.get('year'),'All classes')}${select('Sort by','sort',['Name',...cats],sort)}</div><p class="count">${list.length} ${list.length===1?'player':'players'} · Tap a name to open their record</p><div class="player-grid">${list.map(playerCard).join('')}</div>${!list.length?'<p class="empty">No players match. Try another name or graduation year.</p>':''}${note()}`}
let teamLogos={};
function opponentMark(name){const logo=teamLogos[name];if(logo?.sprite){const b=logo.sprite,k=Math.min(44/b.width,44/b.height);return `<span class="opponent-mark" aria-hidden="true"><span class="opponent-banner" style="display:block;width:${b.width*k}px;height:${b.height*k}px;background-image:url('${esc(logo.file)}');background-size:${b.fullWidth*k}px ${b.fullHeight*k}px;background-position:${-b.x*k}px ${-b.y*k}px;${b.clip?'clip-path:'+b.clip+';':''}"></span></span>`;}const letters=name.replace(/\(Inactive\)\s*/,'').split(' ').filter(w=>!['HS','School','Academy','(PA)'].includes(w)).slice(0,2).map(w=>w[0]).join('');return `<span class="opponent-mark" aria-hidden="true"><span class="opponent-initials" ${logo?'hidden':''}>${esc(letters)}</span>${logo?`<img src="${esc(logo.file)}" alt="" width="44" height="44" loading="lazy">`:''}</span>`}
function playerMatch(s){const g=D.games.find(g=>g.id===s.id);const result=g?.result;return `<article class="match-card"><div class="match-meta"><time>${date(s.date)}</time><span>${esc(s.phase)}${g?.homeAway==='H'?' · Home':g?.homeAway==='A'?' · Away':''}</span></div><div class="match-opponent">${opponentMark(s.opponent)}<h3>${esc(s.opponent)}</h3><div class="match-result ${result==='L'?'lost':''}"><span>${result==='W'?'WIN':result==='L'?'LOSS':'RESULT'}</span><strong>${esc(g?.score||'—')}</strong></div></div><div class="match-numbers" aria-label="Player statistics">${playerStatstrip(s.values)}</div><div class="match-actions"><a href="${route('game',{id:s.id})}">Game details <span aria-hidden="true">→</span></a>${source(s.source,'View Results')}</div></article>`}
function player(q){const p=D.players.find(p=>p.id===q.get('id'));if(!p)return missing('player');const rows=D.stats.filter(s=>s.name===p.name).sort((a,b)=>serial(b.date)-serial(a.date));const seasons=[...new Set([...rows.map(r=>r.season),...D.roster.filter(r=>r.name===p.name).map(r=>r.season)])].sort((a,b)=>b-a);const selected=cats[Number(q.get('stat'))]&&q.has('stat')?Number(q.get('stat')):-1;const visible=rows.filter(s=>!q.get('season')||String(s.season)===q.get('season'));if(selected>=0)visible.sort((a,b)=>(b.values[selected]??-1)-(a.values[selected]??-1)||serial(b.date)-serial(a.date));return `<div class="player-page"><a class="back" href="${route('players',{year:p.year})}">← ${p.year==='Unknown'?'All players':'Class of '+p.year}</a><div class="profile-title player-poster">${jerseyMark(p.name)}<div class="eyebrow">ARCHMERE · GIRLS VARSITY</div><h1>${esc(p.name)}</h1>${currentRosterDetail(p.name)}<p>${p.year==='Unknown'?'Graduation year unknown':'Class of '+p.year}<span> · </span>${esc(seasons.length?seasons.slice().reverse().join(', '):'Roster record')}</p></div><section class="player-career" aria-label="Career totals"><h2>Career totals</h2>${playerStatstrip(p.values)}<p>Tap a number to explore that stat. <a href="#about">Coverage notes</a></p></section><details class="season-breakdown"><summary>Season totals <span>${seasons.length} seasons</span></summary><div class="season-grid">${seasons.map(y=>{const ss=rows.filter(r=>r.season===y);return `<div class="card season-card"><h3><a href="${route('season',{year:y})}">${y} season →</a></h3>${playerStatstrip(total(ss))}<small>${ss.length} published stat entries</small></div>`}).join('')}</div></details><section class="player-game-section"><div class="section-head"><h2>Game by game</h2><span class="quiet">${visible.length} stat entries</span></div><div class="log-filter">${select('Season','season',seasons,q.get('season'),'All seasons')}<p>${selected<0?'Newest first':'Highest '+cats[selected].toLowerCase()+' first'} · A dash means unreported.</p></div><div class="stat-switch player-stat-switch" role="group" aria-label="Rank player games"><button type="button" data-player-stat="all" aria-pressed="${selected<0}">Newest</button>${cats.map((c,i)=>`<button type="button" data-player-stat="${i}" aria-pressed="${selected===i}">${c}</button>`).join('')}</div><div class="stat-story" aria-live="polite">${playerStatStory(visible,selected)}</div><div class="match-list ranked-matches">${visible.map(playerMatch).join('')}</div>${!visible.length?'<p class="empty">No published game stats are available for this season.</p>':''}</section><details class="player-source-note"><summary>About this player’s records</summary><p>${esc(p.note)}</p><p>Totals include available published statistics. Missing stats are not counted as zero. Stat entries do not establish games played.</p><p>Opponent marks identify schools; they may differ from historical logos. Initials appear where a logo is unavailable.</p></details></div>`}

function games(q){const list=D.games.filter(g=>(!q.get('season')||String(g.season)===q.get('season'))&&(!q.get('search')||g.opponent.toLowerCase().includes(q.get('search').toLowerCase()))&&(!q.get('phase')||g.phase===q.get('phase'))&&(q.get('coverage')!=='Missing player stats'||!g.entries)).sort((a,b)=>serial(b.date)-serial(a.date));return head('Game center','Every available result page, with scores, player statistics and a direct link to the original source.')+`<div class="tools">${search('Search opponents',q.get('search'))}${select('Season','season',years(),q.get('season'),'All seasons')}${select('Competition','phase',['Regular','Postseason'],q.get('phase'),'All games')}${select('Coverage','coverage',['Missing player stats'],q.get('coverage'),'All results')}</div><p class="count">${list.length} result pages · Most recent first</p><div class="game-list">${list.map(gameCard).join('')}</div>${!list.length?'<p class="empty">No games match these filters.</p>':''}`}
function boxRows(rows,selected=-1){
 const sorted=[...rows].sort((a,b)=>selected<0?a.name.localeCompare(b.name):(b.values[selected]??-1)-(a.values[selected]??-1)||a.name.localeCompare(b.name));
 return sorted.map((r,index)=>`<div class="box-player" style="--row-delay:${Math.min(index,6)*35}ms"><a href="${pLink(r.name)}"><span>${selected>=0&&r.values[selected]!=null?`<small class="stat-rank">${1+rows.filter(x=>(x.values[selected]??-1)>r.values[selected]).length}</small>`:''}<span class="box-player-identity">${esc(r.name)}${currentRosterDetail(r.name)}</span></span><span aria-hidden="true">↗</span></a><div class="stat-strip">${cats.map((c,i)=>`<div class="stat-cell ${selected===i?'is-selected':''} ${selected>=0&&selected!==i?'is-muted':''}"><strong>${fmt(r.values[i])}</strong><span>${c}</span></div>`).join('')}</div></div>`).join('');
}
document.addEventListener('click',e=>{
 const button=e.target.closest('[data-box-stat]');if(!button)return;
 const panel=button.closest('.box-explorer'),selected=button.dataset.boxStat==='all'?-1:Number(button.dataset.boxStat);
 const rows=D.stats.filter(s=>s.id===panel.dataset.game);
 panel.querySelectorAll('[data-box-stat]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));
 panel.querySelector('.box-players').innerHTML=boxRows(rows,selected);
 const story=panel.querySelector('.stat-story');
 if(selected<0){story.textContent='Tap a stat to see this match’s leaders.';return;}
 const reported=rows.filter(r=>r.values[selected]!=null),max=Math.max(0,...reported.map(r=>r.values[selected]));
 const leaders=reported.filter(r=>r.values[selected]===max);
 story.innerHTML=!reported.length?`No ${cats[selected].toLowerCase()} were reported for this match.`:max===0?`All reported ${cats[selected].toLowerCase()} totals are zero.`:`<strong>${max}</strong><span><b>${leaders.map(r=>esc(r.name)).join(' & ')}</b><small>${leaders.length>1?'Tied for the match lead in':'Match leader in'} ${cats[selected].toLowerCase()}</small></span>`;
});
function game(q){
 const g=D.games.find(g=>g.id===q.get('id'));if(!g)return missing('game');
 const rows=D.stats.filter(s=>s.id===g.id).sort((a,b)=>a.name.localeCompare(b.name));
 const issues=D.issues.filter(i=>String(i.id)===String(g.id));
 const sets=(g.sets||[]).filter(Boolean),score=(g.score||'').split(/[-–:]/);
 const label=g.result==='W'?'Auks take the match':g.result==='L'?'Match final':'From the match archive';
 return `<article class="game-report"><a class="back" href="${route('games',{season:g.season})}">← ${g.season} schedule</a>
 <div class="match-dateline"><span>THE MATCH BOOK</span><span>${esc(g.season)} / GIRLS VARSITY</span></div>
 <h1 class="report-title">${label}<span>.</span></h1>
 <p class="report-date">${date(g.date)} <span>·</span> ${esc(g.phase)} <span>·</span> ${g.homeAway==='H'?'At Archmere':'Away match'}</p>
 <section class="match-scorecard" aria-label="Match result">
 <div class="final-label">${g.result?'FINAL SCORE':'RECORDED RESULT'}</div>
 <div class="match-teams">
 <div class="match-team ${g.result==='W'?'match-winner':''}"><div class="team-crest"><img src="archmere-auks.jpg" alt="Archmere Auks logo"></div><h2>Archmere</h2><span class="team-caption">AUKS</span><strong class="team-score">${esc(score[0]||'—')}</strong>${g.result==='W'?'<span class="winner-label">WIN</span>':''}</div>
 <span class="versus">VS</span>
 <div class="match-team ${g.result==='L'?'match-winner':''}"><div class="team-crest">${opponentMark(g.opponent)}</div><h2>${esc(g.opponent)}</h2><span class="team-caption">${g.homeAway==='H'?'VISITOR':'HOME TEAM'}</span><strong class="team-score">${esc(score[1]||'—')}</strong>${g.result==='L'?'<span class="winner-label">WIN</span>':''}</div>
 </div>
 <div class="scorecard-foot"><span>${sets.length?sets.length+' sets played':'Varsity volleyball'}</span>${source(g.url,'Official results')}</div></section>
 <section class="report-sets"><div class="report-section-title"><span>01</span><h2>Set by set</h2></div>${sets.length?`<div class="set-recap">${sets.map((v,i)=>{const n=String(v).split(/[-–:]/),won=Number(n[0])>Number(n[1]);return `<div class="recap-set"><span>SET ${i+1}</span><strong>${esc(v)}</strong><small>${won?'Archmere':Number(n[1])>Number(n[0])?esc(g.opponent):'Recorded score'}</small></div>`}).join('')}</div><p class="set-key">Scores listed Archmere first.</p>`:'<p class="archive-empty">Set scores aren’t listed in the official results for this match.</p>'}</section>
 <section class="report-box"><div class="report-section-title"><span>02</span><h2>The box score</h2></div><p class="box-subtitle">Archmere player statistics</p>
 ${rows.length?`<div class="box-explorer" data-game="${esc(g.id)}"><div class="stat-switch" role="group" aria-label="Rank players by statistic"><button type="button" data-box-stat="all" aria-pressed="true">All stats</button>${cats.map((c,i)=>`<button type="button" data-box-stat="${i}" aria-pressed="false">${c}</button>`).join('')}</div><div class="stat-story" aria-live="polite">Tap a stat to see this match’s leaders.</div><div class="box-players">${boxRows(rows)}</div><p class="bar-key">Tap a category to rank players. A dash means unreported, not zero.</p></div>`:'<div class="archive-empty"><h3>No player stats published</h3><p>The match result is on record. Individual stats weren’t available on the official results page.</p></div>'}
 <details class="box-notes"><summary>About these statistics</summary>${note()}</details></section>
 ${issues.length?`<details class="box-notes"><summary>Source notes for this match (${issues.length})</summary>${issues.map(i=>`<div class="note"><b>${esc(i.name)}</b><p>${esc(i.reason)}</p><p>Published text: ${esc(i.raw)}</p></div>`).join('')}</details>`:''}
 <a class="report-next" href="${route('games',{season:g.season})}"><span>BACK TO THE SEASON</span><strong>More from ${g.season} <span>→</span></strong></a></article>`;
}
function records(q){const scope=q.get('scope')||'Career',cat=q.get('category')||'Kills',ci=cats.indexOf(cat);let list=[];if(scope==='Career')list=D.players.map(p=>({name:p.name,value:p.values[ci],detail:p.year==='Unknown'?'Graduation unknown':'Class of '+p.year,url:pLink(p.name)}));else if(scope==='Season'){const groups=new Map();D.stats.forEach(s=>{const key=s.name+'|'+s.season;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(s)});list=[...groups.values()].map(rows=>({name:rows[0].name,value:total(rows)[ci],detail:rows[0].season+' season',url:route('player',{id:pByName(rows[0].name).id,season:rows[0].season})}));}else list=D.stats.map(s=>({name:s.name,value:s.values[ci],detail:date(s.date)+' · '+s.opponent,url:route('game',{id:s.id})}));list=list.filter(x=>x.value!=null).sort((a,b)=>b.value-a.value||a.name.localeCompare(b.name));let rank=0,prev;list=list.map((x,i)=>{if(x.value!==prev)rank=i+1;prev=x.value;return {...x,rank}}).filter(x=>x.rank<=10);return head('Record leaders','Career, season and single-game leaders. Top 10 ranks, including ties.')+`<div class="tools">${select('Record scope','scope',['Career','Season','Single game'],scope)}${select('Statistic','category',cats,cat)}</div><p class="note" style="margin:0 0 20px">Incomplete historical coverage means these are documented leaders, not certified all-time school records.</p><div class="leader-list">${list.map(x=>`<a class="leader-row" href="${x.url}"><span class="rank">${x.rank}</span><div><h3>${esc(x.name)}</h3><small>${esc(x.detail)}</small></div><span class="score">${fmt(x.value)}</span></a>`).join('')}</div>`}
function seasons(){return head('Season archive','Explore team results, rosters and the availability of player statistics across 21 seasons.')+`<div class="season-grid section">${years().map(y=>{const gs=D.games.filter(g=>g.season===y),w=gs.filter(g=>g.result==='W').length,l=gs.filter(g=>g.result==='L').length;return `<a class="card season-card" href="${route('season',{year:y})}"><div class="section-head"><h2>${y}</h2><span class="score">${w}–${l}</span></div><p>${gs.length} available result pages</p><small>${gs.filter(g=>g.entries).length} games with player statistics · Explore season ↗</small></a>`}).join('')}</div>${note()}`}
function season(q){const year=Number(q.get('year'));if(!years().includes(year))return missing('season');const gs=D.games.filter(g=>g.season===year).sort((a,b)=>serial(b.date)-serial(a.date)),rows=D.stats.filter(s=>s.season===year),roster=D.roster.filter(r=>r.season===year);return `<a class="back" href="#seasons">← Season archive</a>${head(year+' season',`${gs.filter(g=>g.result==='W').length} wins · ${gs.filter(g=>g.result==='L').length} losses · ${gs.length} available result pages`)}<section class="career"><div class="eyebrow">DOCUMENTED SEASON TOTALS</div>${statstrip(total(rows))}</section><p class="note">${gs.filter(g=>g.entries).length} of ${gs.length} result pages have usable player statistics. Totals reflect available entries only.</p><section class="section"><h2>Roster</h2><div class="chips" style="margin-top:16px">${roster.map(r=>`<a class="chip" href="${pLink(r.name)}">${esc(r.name)}${r.role==='Manager'?' · Manager':''} ↗</a>`).join('')||'<p class="quiet">No archived roster is available for this season.</p>'}</div></section><section class="section"><div class="section-head"><h2>Results</h2></div><div class="game-list">${gs.map(gameCard).join('')}</div></section>`}
function about(){return head('Behind the numbers','A transparent record book built from published Archmere girls varsity volleyball results.')+`<div class="about-grid"><section class="card"><h2>What’s included</h2><p>336 result pages across the 2006–2026 archive, 104 listed players and 3,325 published player-game entries. Varsity regular-season and postseason records are included.</p><p>Updated ${D.updated}. This is a snapshot, not a live connection to Google Sheets. New records and corrections require a site update.</p></section><section class="card"><h2>Read the stats fairly</h2><p>278 games have usable Archmere player statistics; 58 have scores without usable player stats. A dash means unreported. Zero means a published zero. Source rows may include nonparticipants and are not a games-played count.</p><p><a href="${route('games',{coverage:'Missing player stats'})}">Explore games with missing stats ↗</a></p></section><section class="card"><h2>Sources & method</h2><p>Each archived season was selected on AuksSports and each available View Results link was opened. Player tables and written summaries were reconciled against seasonal rosters. Every game retains its original result link.</p><p><a href="https://www.aukssports.com/teams/gvb/teamstats" target="_blank" rel="noopener noreferrer">Visit AuksSports ↗</a></p></section><section class="card"><h2>Graduation years & corrections</h2><p>Expected graduation is usually derived from the published roster grade. Missing or conflicting grades stay Unknown. Patreece Spence’s graduation year is 2011, as corrected by the record-book owner.</p><p>The two unverified Lillian Guzevich assists remain excluded. Her documented career assists total 973.</p></section></div><section class="section"><h2>Entries held for review</h2><p class="intro">${D.issues.length} ambiguous or incomplete stat lines are excluded from numeric totals. No missing categories have been guessed.</p><div class="stack section">${D.issues.map(i=>`<details class="card"><summary>${esc(i.name||'Source entry')} · ${esc(i.season)}</summary><p>${esc(i.reason)}</p><p class="quiet">${esc(i.raw)}</p>${source(i.source)}</details>`).join('')}</div></section><p class="note">This independent record book is not an official school publication. Historical gaps mean totals should not be presented as certified all-time school records.</p>`}
function missing(what){return `<h1>That ${what} wasn’t found.</h1><p class="intro">Return to the record book to continue browsing.</p><a class="button section" href="#home">Back to home</a>`}
function roster(){const year=Math.max(...D.roster.map(r=>r.season));const list=D.roster.filter(r=>r.season===year&&r.role!=='Manager').sort((a,b)=>Number(a.jersey)-Number(b.jersey));return head('Current roster',`${year} girls varsity · ${list.length} players. Tap a player for career stats and game results.`)+`<div class="chips section"><a class="chip" href="${route('season',{year})}">${year} season overview →</a><a class="chip" href="${route('games',{season:year})}">Season results →</a></div><div class="player-grid section">${list.map(r=>{const p=pByName(r.name);return `<a class="card player-card" href="${pLink(r.name)}"><div class="top">${jerseyMark(r.name)}<div><h3>${esc(r.name)}</h3><small>Grade ${esc(r.grade)}${p&&p.year!=='Unknown'?' · Class of '+p.year:''}</small></div><span class="arrow" aria-hidden="true">↗</span></div><p class="quiet">${year} season totals</p>${statstrip(total(D.stats.filter(s=>s.name===r.name&&s.season===year)))}</a>`}).join('')}</div>${note()}<p class="quiet section">Roster snapshot updated ${D.updated}. <a href="https://www.aukssports.com/teams/gvb/roster" target="_blank" rel="noopener noreferrer">School roster ↗</a></p>`}
const pages={home,roster,players,player,games,game,records,seasons,season,about};
function render(reset=true){if(!D)return;const {page,q}=getState();const active=page==='player'?'players':page==='game'?'games':page==='season'?'seasons':page;$('#nav').innerHTML=[['home','Home'],['roster','Current Roster'],['players','Players'],['games','Games'],['records','Records'],['seasons','Seasons']].map(([id,label])=>`<a class="${active===id?'active':''}" href="#${id}" ${active===id?'aria-current="page"':''}>${label}</a>`).join('');$('#main').innerHTML=(pages[page]||home)(q);const p=page==='player'?D.players.find(p=>p.id===q.get('id')):null;document.title=(p?p.name:page==='home'?'Archmere Volleyball':page[0].toUpperCase()+page.slice(1))+' · Record Book';if(reset)window.scrollTo(0,0);}
document.addEventListener('change',e=>{if(e.target.matches('[data-filter]'))updateFilter(e.target,false)});
let searchTimer;document.addEventListener('input',e=>{if(e.target.matches('input[data-filter]')){clearTimeout(searchTimer);searchTimer=setTimeout(()=>updateFilter(e.target,true),180)}});
function updateFilter(input,focus){const {page,q}=getState(),key=input.dataset.filter,value=input.value,position=input.selectionStart;if(value)q.set(key,value);else q.delete(key);history.replaceState(null,'',route(page,Object.fromEntries(q)));render(false);if(focus){const el=$('#search');el?.focus();if(position!=null)el?.setSelectionRange(position,position)}}
window.addEventListener('hashchange',()=>render());
$('.skip').addEventListener('click',e=>{e.preventDefault();$('#main').focus();});
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
$('#share').addEventListener('click',async()=>{const data={title:document.title,url:location.href};try{if(navigator.share){await navigator.share(data);return}await navigator.clipboard.writeText(location.href);toast('Link copied. Ready to share!')}catch(e){if(e.name!=='AbortError')prompt('Copy this link to share:',location.href)}});
Promise.all([fetch('data.json').then(r=>{if(!r.ok)throw Error('Data unavailable');return r.json()}),fetch('opponents.json').then(r=>r.ok?r.json():{}).catch(()=>({}))]).then(([d,logos])=>{D=d;teamLogos=logos;render()}).catch(()=>{$('#main').innerHTML='<div class="empty"><h1>Couldn’t load the record book.</h1><p>Please refresh the page to try again.</p></div>'});

document.addEventListener('error',e=>{if(e.target.matches?.('.opponent-mark img')){e.target.hidden=true;e.target.previousElementSibling.hidden=false;}},true);
